def _build(row: dict) -> MetricSpec:
    finance_stage = row.get("finance_stage")
    return MetricSpec(
        key=row["key"],
        label=row["label"],
        definition=row["definition"],
        question=row["question"],
        category=Category(row["category"]),
        unit=Unit(row["unit"]),
        service=row["service"],
        source_models=tuple(row["source_models"]),
        numerator=row["numerator"],
        denominator=row.get("denominator"),
        date_basis=DateBasis(row["date_basis"]),
        period=Period(row["period"]),
        scope=row["scope"],
        owner_page=row["owner_page"],
        filter_behaviour=FilterBehaviour(row["filter_behaviour"]),
        finance_stage=FinanceStage(finance_stage) if finance_stage else None,
        drilldown=row.get("drilldown"),
        no_drilldown_reason=row.get("no_drilldown_reason"),
        roles=tuple(row.get("roles", ())),
        notes=row.get("notes", ""),
        source_location=row.get("source_location"),
    )


RECONCILED_METRICS: tuple[MetricSpec, ...] = tuple(
    _build(row) for row in RECONCILED_METRIC_ROWS
)
_KEY_BY_SOURCE_LABEL = {
    (row["source"], row["source_label"]): row["key"] for row in RECONCILED_METRIC_ROWS
}
_SOURCE_LABEL_BY_KEY = {
    row["key"]: row["source_label"] for row in RECONCILED_METRIC_ROWS
}


def key_for_source_label(source: str, label: str) -> str:
    try:
        return _KEY_BY_SOURCE_LABEL[(source, label)]
    except KeyError:
        raise KeyError(
            f"unregistered metric label {label!r} from {source!r}; add it to "
            "the reconciled metric registry before rendering it"
        ) from None


def source_label_for_key(key: str) -> str:
    """Legacy server-contract label; templates display MetricSpec.label."""
    return _SOURCE_LABEL_BY_KEY[key]
